    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    cin >> s;

    const string target = "CODEFORCES";
    int n = s.length();
    int m = target.length();

    bool ok = false;
    if (n >= m) {
        for (int i = 0; i <= m; ++i) {
            // Check prefix of length i and suffix of length m-i
            bool prefix_ok = (s.substr(0, i) == target.substr(0, i));
            bool suffix_ok = (s.substr(n - (m - i)) == target.substr(i));
            if (prefix_ok && suffix_ok) {
                ok = true;
                break;
            }
        }
    }

    cout << (ok ? "YES" : "NO") << endl;
    return 0;
}

